package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.Statements;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement on the sheet's today: records their due-total, binds each of their counting claims
 * to the figure it has now, and unbinds the rest. A claim's figure is its settled due when it has one, else the
 * figure its last statement bound it to, else its amount times its person's grade's rate in force on the claim's
 * date (rounded half to even, and at least the sheet's floor; none without a rate). The due-total is the counting claims' figures added up; n/a
 * (null) when the grade has no rate today and no counting claim keeps a settled or bound figure.
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, RateRepository rates, SheetRepository sheets,
            SettingRepository settings, StatementRepository statements, Out<Statement> taken) {
        String sheetId = person.getSheetId();
        LocalDate today = sheets.today(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        List<Claim> mine = claims.listOf(sheetId, person.getId());
        BigDecimal sum = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        for (Claim c : mine) {
            if (!c.getStatus().counts()) {
                claims.bind(c.getId(), false, null);
                continue;
            }
            counted++;
            kept |= c.getSettledDue() != null || (c.isStated() && c.getStatedDue() != null);
            BigDecimal figure = figure(c, person, rates, floor);
            if (figure != null) {
                sum = sum.add(figure);
            }
            claims.bind(c.getId(), true, figure);
        }
        BigDecimal dueTotal = kept || rates.find(sheetId, person.getGrade(), today) != null ? sum : null;
        statements.insert(sheetId, person.getId(), dueTotal, today);
        person.setStatements(new Statements(person.getStatements().count() + 1, dueTotal, today));
        taken.set(new Statement(dueTotal, counted));
    }

    private static BigDecimal figure(Claim claim, Person person, RateRepository rates, BigDecimal floor) {
        if (claim.getSettledDue() != null) {
            return claim.getSettledDue();
        }
        if (claim.isStated()) {
            return claim.getStatedDue();
        }
        BigDecimal rate = rates.find(claim.getSheetId(), person.getGrade(), claim.getDate());
        return rate == null ? null
                : claim.getAmount().multiply(rate).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN).max(floor);
    }
}
}

/** A person's due-total in cents: their counted claims' already-rounded figures added up (0 with none). Null when
 *  their grade has no rate on the sheet's today, unless a counted settled or stated claim keeps a figure: then the figures
 *  there are, added up. */
function useDueTotals(sheetId: string): Map<number, bigint | null> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const today = useRateByGrade(sheetId);
  const held = useHeld(sheetId);
  const floor = useFloorCents(sheetId);
  const totals = new Map<number, bigint | null>();
  for (const p of people.data ?? []) {
    const counted = (claims.data ?? []).filter((c) => c.personId === p.id && counts(c, held));
    if (!today.has(p.grade) && !counted.some((c) => c.settledDue != null || (c.stated && c.statedDue != null))) {
      totals.set(p.id, null);
      continue;
    }
    let sum = 0n;
    for (const c of counted) sum += claimDueCents(rates.data ?? [], p.grade, c, floor) ?? 0n;
    totals.set(p.id, sum);
  }
  return totals;
}

// The rate form: sets a grade's rate from a date (blank: from the beginning of time), replacing one
// already set for that grade and date. Every rate is listed under it, with each grade's rate in
// force on the sheet's today.
function RatesPanel({ sheetId }: { sheetId: string; user: string }) {
  const rates = useRates(sheetId);
// A person's due-total: their counted claims' due figures added up; n/a when the grade has no rate today and
// no settled or stated claim keeps a figure.
function DueTotalCell({ sheetId, personId }: { sheetId: string; user: string; personId: number }) {
  const total = useDueTotals(sheetId).get(personId);
  return <td data-testid="person-due-total">{total == null ? NA : showHundredths(total)}</td>;
}

// A claim's due: fixed when it was settled; the bound figure while a statement binds it; otherwise its amount times its person's grade's rate in
// force on the claim's date (at least the sheet's floor), n/a when no rate of the grade applies then.
function ClaimDue({ sheetId, personId, claim }: { sheetId: string; user: string; personId: number;
  claim: { amount: string; date: string; settledDue: string | null; stated: boolean; statedDue: string | null } }) {
  const people = usePeople(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloorCents(sheetId);
  const grade = people.data?.find((p) => p.id === personId)?.grade;
  const due = claimDueCents(rates.data ?? [], grade, claim, floor);
  return <span data-testid="claim-due">{due == null ? NA : showHundredths(due)}</span>;
}

// The sheet's due-total: everyone's due-total added up, skipping those that are n/a.
function DueTotal({ sheetId }: { sheetId: string; user: string }) {
  const totals = useDueTotals(sheetId);
  let sum = 0n;
  for (const t of totals.values()) if (t != null) sum += t;
  return (
    <section data-testid="due-rollup">
      <p>
        Due total: <strong data-testid="rollup-due-total">{showHundredths(sum)}</strong>
      </p>
    </section>
  );
// The period form: adds a period with a name unique on the sheet and a from and to date, not
// overlapping another period. Every period is listed under it with its due-total: the due figures of
// the counted claims whose date falls in it, added up.
function PeriodsPanel({ sheetId }: { sheetId: string; user: string }) {
  const periods = usePeriods(sheetId);
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const held = useHeld(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloorCents(sheetId);
  const [name, setName] = useState('');
  const [from, setFrom] = useState('');
  const [to, setTo] = useState('');
  const [user] = useUser();
  const queryClient = useQueryClient();
  const save = useMutation({
    mutationFn: async (body: { name: string; from: string; to: string }) => {
      if (body.name.trim() === '') throw new Error('Enter a period name');
      if (body.to.trim() === '') throw new Error('Enter a to-date');
      if ((body.from.trim() !== '' && !DATE.test(body.from.trim())) || !DATE.test(body.to.trim())) {
        throw new Error('Enter a date as YYYY-MM-DD');
      }
      // `by` is the signed-in user the change is recorded against.
      return postJson<Period>(`/api/sheets/${encodeURIComponent(sheetId)}/periods`, {
        name: body.name.trim(), from: body.from.trim(), to: body.to.trim(), by: user ?? '' });
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
      setName('');
      setFrom('');
      setTo('');
    },
  });
  const field = (set: (v: string) => void) => (e: ChangeEvent<HTMLInputElement>) => {
    set(e.target.value);
    save.reset();
  };

  const gradeOf = new Map((people.data ?? []).map((p) => [p.id, p.grade]));
  const dueTotal = (p: Period): bigint => {
    let sum = 0n;
    for (const c of claims.data ?? []) {
      if (!counts(c, held) || c.date < p.from || c.date > p.to) continue;
      sum += claimDueCents(rates.data ?? [], gradeOf.get(c.personId), c, floor) ?? 0n;
    }
    return sum;
  };

  const submit = useSubmitOnce(save);
  return (
    <section data-testid="periods-panel">
